using System.Diagnostics;using System.Text.Json;using Microsoft.Extensions.Options;
namespace Orchestration.API.Engineering.Adapters.Codebeamer;
public interface ICodebeamerCliClient { Task<CodebeamerStatusDto> StatusAsync(CancellationToken token); Task<CodebeamerSearchDto> SearchAsync(string query,int limit,CancellationToken token); }
public sealed class CodebeamerCliClient:ICodebeamerCliClient
{
 readonly CodebeamerOptions options;static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,PropertyNamingPolicy=JsonNamingPolicy.SnakeCaseLower};public CodebeamerCliClient(IOptions<CodebeamerOptions> options)=>this.options=options.Value;
 public async Task<CodebeamerStatusDto> StatusAsync(CancellationToken token)=>Deserialize<CodebeamerStatusDto>(await RunAsync(["status","--json"],token));public async Task<CodebeamerSearchDto> SearchAsync(string query,int limit,CancellationToken token)=>Deserialize<CodebeamerSearchDto>(await RunAsync(["search",query,"--limit",Math.Clamp(limit,1,500).ToString(),"--json"],token));T Deserialize<T>(string value)=>JsonSerializer.Deserialize<T>(value,Json)??throw new InvalidOperationException("Codebeamer returned an empty JSON contract.");
 async Task<string> RunAsync(IReadOnlyList<string> args,CancellationToken token){var working=Path.GetFullPath(options.WorkingDirectory);if(!Directory.Exists(working))throw new DirectoryNotFoundException($"Codebeamer extractor directory was not found: {working}");var exe=options.ExecutablePath;if(string.IsNullOrWhiteSpace(exe))exe=OperatingSystem.IsWindows()?Path.Combine(working,".venv","Scripts","codebeamer-extractor.exe"):Path.Combine(working,".venv","bin","codebeamer-extractor");if(!File.Exists(exe))throw new FileNotFoundException("Codebeamer extractor executable was not found.",exe);using var p=new Process{StartInfo=new ProcessStartInfo{FileName=exe,WorkingDirectory=working,RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false,CreateNoWindow=true}};foreach(var a in args)p.StartInfo.ArgumentList.Add(a);if(!p.Start())throw new InvalidOperationException("Codebeamer extractor process could not be started.");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(Math.Clamp(options.CommandTimeoutSeconds,1,300)));using var linked=CancellationTokenSource.CreateLinkedTokenSource(token,timeout.Token);var stdout=p.StandardOutput.ReadToEndAsync(linked.Token);var stderr=p.StandardError.ReadToEndAsync(linked.Token);try{await p.WaitForExitAsync(linked.Token);}catch{try{p.Kill(true);}catch{}throw;}var output=await stdout;var error=await stderr;if(output.Length>options.MaximumOutputCharacters)throw new InvalidOperationException("Codebeamer output exceeded the configured safety limit.");if(p.ExitCode!=0)throw new InvalidOperationException($"Codebeamer command failed with exit code {p.ExitCode}: {(error.Length<=2000?error:error[..2000])}");return output;}
}
